import { StreamError } from '../../../index';

/** A 4x4 JPEG, for image upload fixtures (write it to an `os.tmpdir()` dir or wrap it in a `File`). */
export const JPEG_BASE64 =
  '';

/** The bytes of `JPEG_BASE64`. */
export const jpeg = Buffer.from(JPEG_BASE64, 'base64');

/** A minimal PDF, for file upload fixtures. */
export const MINIMAL_PDF = '%PDF-1.4\n%%EOF\n';

/** Swallows the 404 of deleting an upload that is already gone. */
export const ignoreMissingFile = (error: unknown) => {
  if (error instanceof StreamError && error.metadata?.responseCode === 404) {
    return;
  }
  throw error;
};
